export function ClearTabs({
  items,
  value,
  onChange,
  label = "页面分区",
  disabled = false
}) {
  const id = useId(),
    active = items.find(item => item.id === value) ?? items[0];
  const change = (e, index) => {
    const enabled = items.filter(i => !i.disabled);
    const pos = enabled.findIndex(i => i.id === items[index].id);
    const offset = e.key === "ArrowRight" ? 1 : e.key === "ArrowLeft" ? -1 : 0;
    const next = e.key === "Home" ? enabled[0] : e.key === "End" ? enabled.at(-1) : offset ? enabled[(pos + offset + enabled.length) % enabled.length] : null;
    if (next) {
      e.preventDefault();
      onChange?.(next.id);
      document.getElementById(id + "-" + next.id)?.focus();
    }
  };
  return <div><div className="cc-tabs" role="tablist" aria-label={label}>{items.map((item, index) => <button type="button" role="tab" id={id + "-" + item.id} aria-controls={id + "-panel"} key={item.id} aria-selected={active?.id === item.id} tabIndex={active?.id === item.id ? 0 : -1} disabled={disabled || item.disabled} onKeyDown={e => change(e, index)} onClick={() => onChange?.(item.id)}>{item.label}</button>)}</div><section role="tabpanel" id={id + "-panel"} aria-labelledby={id + "-" + active?.id} tabIndex={0}>{active?.content}</section></div>;
}
